   Accepts:
      settings: {block.settings || section.settings}
{%- endcomment -%}

--padding-block-start: {{ settings['padding-block-start'] | default: 0 }}px; --padding-block-end:
{{- settings['padding-block-end'] | default: 0 -}}
px; --padding-inline-start:{{ settings['padding-inline-start'] | default: 0 }}px; --padding-inline-end:
{{- settings['padding-inline-end'] | default: 0 -}}
px;

{% doc %}
  Renders a strikethrough line SVG for unavailable product options.

  @param {object} product_option - The product option object. Renders the strikethrough when product_option.available is false.
{% enddoc %}

{% unless product_option.available %}
  <svg
    viewBox="0 0 100 46"
    preserveAspectRatio="xMidYMid slice"
    class="variant-option__strikethrough"
    aria-hidden="true"
  >
    {% # 25deg %}
    <line x1="100" y1="0" x2="0" y2="46" vector-effect="non-scaling-stroke" />
    {% # duplicate line for motion overlay %}
    <line x1="100" y1="0" x2="0" y2="46" vector-effect="non-scaling-stroke" />
  </svg>
{% endunless %}

{%- comment -%}
  Derives CSS variables from the menu typography settings for 2nd and 3rd level menu items.
  Accepts:
     settings: {block.settings}
{%- endcomment -%}

--menu-parent-font-family: var(--font-{{ settings.type_font_primary_link }}--family); --menu-parent-font-style:
var(--font-
{{- settings.type_font_primary_link -}}
--style); --menu-parent-font-weight: var(--font-
{{- settings.type_font_primary_link -}}
--weight); --menu-parent-font-case:
{% if settings.type_case_primary_link == 'uppercase' %}uppercase{% else %}none{% endif %};
{% case settings.menu_font_style %}
